mapper.select:
SELECT COUNT(*)
FROM sqlite_master
WHERE type = 'table' AND name = #{tableName}

SELECT m.local_id AS localId, m.real_sender_id AS talkerId, CAST(m.server_id AS TEXT) AS msgSvrId, CAST(m.local_type & 4294967295 AS INTEGER) AS type, CAST(m.local_type >> 32 AS INTEGER) AS subType, CASE WHEN n.user_name = #{currentUser} THEN 1 ELSE 0 END AS isSender, CAST(m.create_time AS INTEGER) AS createTime, m.sort_seq AS sequence, m.status AS status, m.server_seq AS msgServerSeq, CAST(m.sort_seq AS INTEGER) AS msgSequence, #{talker} AS strTalker, CAST(m.message_content AS TEXT) AS strContent, NULL AS displayContent, 0 AS reserved0, 0 AS reserved1, 0 AS reserved2, 0 AS reserved3, NULL AS reserved4, NULL AS reserved5, NULL AS reserved6, m.compress_content AS compressContent, m.packed_info_data AS bytesExtra, m.source AS bytesTrans, m.message_content AS rawContent, n.user_name AS senderUserName FROM [${tableName}] m LEFT JOIN Name2Id n ON n.rowid = m.real_sender_id WHERE 1 = 1
AND m.sort_seq < #{nextSequence}
ORDER BY m.sort_seq DESC, m.local_id DESC LIMIT #{limit}
